import {isPico,encodeBytes} from './unified-project.js';
import {boardKey} from './board-hardware.js';
import {nativeSDKImage} from './pico-sdk-image.js';
import {sourceKey} from './source-files.js';
export function installPicoSDK({getProject,showDialog,download,adopt,onError}){
 const button=document.createElement('button');button.textContent='Pico SDK / CMake';button.hidden=true;document.querySelector('.menubar nav').append(button);
 button.onclick=()=>{showDialog('Resmi Pico SDK / CMake','<p>Tarayıcıdaki hızlı derleme küçük SDK ve bildirimsel CMake alt kümesini kullanır. Tam CMake komutlarını ve resmi SDK kütüphanelerini bilgisayarınızdaki gerçek araçlarla derleyebilirsiniz. Sonuç UF2 dosyası burada özgün ROM üzerinden açılır ve devreye bağlanır.</p><ol><li>Projeyi JSON olarak kaydedin.</li><li><a href="./build-pico-sdk.py" download>Yerel derleme aracını indirin</a>. Resmi <a href="https://github.com/raspberrypi/pico-sdk" target="_blank">Pico SDK</a>, Arm GNU, CMake ve Ninja kurulu olmalı.</li><li>Aşağıdaki komutu kendi klasör yollarınızla çalıştırın. CMake, kaynak projenizdeki komutları gerçekten yürütür; yalnız güvendiğiniz projeleri derleyin.</li><li>Çıktıdaki UF2 dosyasını seçip Çalıştır’a basın. W kartlarında gerçek radyo/CYW43 yürütümü desteklenmez. Native SDK için kaynak satırı debug eşlemesi henüz yoktur.</li></ol><pre style="white-space:pre-wrap">python build-pico-sdk.py --project proje.json --sdk pico-sdk --toolchain arm-gnu --output sonuc</pre><p><a href="./notices/PICO-SDK-NATIVE.md" target="_blank">Kurulum, örnek ve kapsam</a></p><label>Resmi SDK UF2 yükle <input id="pico-sdk-uf2" type="file" accept=".uf2"></label><p id="pico-sdk-result"></p>');
 const input=document.getElementById('pico-sdk-uf2'),status=document.getElementById('pico-sdk-result');input.onchange=async()=>{const file=input.files[0],p=getProject(),id=boardKey(p);if(!file)return;try{if(file.size>1000000)throw Error('Bu proje aktarımında UF2 en fazla 1 MB olabilir.');const image=nativeSDKImage(new Uint8Array(await file.arrayBuffer()),id);if(getProject()!==p)throw Error('Dosya okunurken proje değişti.');const next=structuredClone(p);next.settings.picoArchitecture='arm';next.firmware={format:'pico-sdk-bin',board:id,payload:encodeBytes(image),source:p.code,sourceKey:sourceKey(next),imported:true,flashBytes:image.length};adopt(next);}catch(e){status.textContent=e.message;onError(e.message);}input.value='';};};
 return {render(){button.hidden=!isPico(getProject())||getProject().language!=='c';}};
}
